import { cn } from '@cascivo/core/pure'
import type { HTMLAttributes, ReactNode } from 'react'
import { Avatar } from '../avatar/avatar'
import type { AvatarProps } from '../avatar/avatar'
import styles from './user.module.css'

export interface UserProps extends HTMLAttributes<HTMLDivElement> {
  /** Primary identity label (name). */
  name: ReactNode
  /** Secondary line (email, role, …). */
  description?: ReactNode
  /** Forwarded to the composed <Avatar>. */
  avatarProps?: AvatarProps
  /** Optional trailing action slot (e.g. a menu button). */
  children?: ReactNode
}

/** Identity composite: an Avatar with a name + optional description and trailing action. */
export function User({ name, description, avatarProps, className, children, ...rest }: UserProps) {
  // Forward the string name to the Avatar so it derives initials (and labels the
  // image), unless the caller already set name/fallback via avatarProps. Spread
  // conditionally so we never pass an explicit `undefined` (exactOptionalPropertyTypes).
  const nameProp =
    typeof name === 'string' &&
    avatarProps?.name === undefined &&
    avatarProps?.fallback === undefined
      ? { name }
      : {}

  return (
    <div role="group" className={cn(styles['user'], className)} {...rest}>
      <Avatar {...nameProp} {...avatarProps} />
      <span className={styles['text']}>
        <span className={styles['name']}>{name}</span>
        {description != null && <span className={styles['description']}>{description}</span>}
      </span>
      {children != null && <span className={styles['action']}>{children}</span>}
    </div>
  )
}

@layer cascivo.component {
  .user {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-3);
    min-inline-size: 0;
    font-family: var(--cascivo-font-sans);
  }

  .text {
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    line-height: var(--cascivo-leading-snug, 1.3);
  }

  .name {
    color: var(--cascivo-color-text);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .description {
    color: var(--cascivo-color-text-muted);
    font-size: var(--cascivo-text-xs);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .action {
    display: inline-flex;
    align-items: center;
    margin-inline-start: var(--cascivo-space-2);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'User',
  description: 'Identity composite: an avatar with a name, description, and optional action slot',
  category: 'display',
  clientJs: 'none',
  states: ['default'],
  variants: [],
  sizes: [],
  props: [
    { name: 'name', description: 'The user’s display name.', type: 'ReactNode', required: true },
    {
      name: 'description',
      description: 'Supporting description text.',
      type: 'ReactNode',
      required: false,
    },
    {
      name: 'avatarProps',
      type: 'AvatarProps',
      required: false,
      description: 'Forwarded to the composed <Avatar>',
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-space-3',
    '--cascivo-text-sm',
    '--cascivo-text-xs',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    {
      title: 'Basic',
      code: '<User name="Jane Doe" description="jane@acme.com" avatarProps={{ src: "/jane.jpg", alt: "Jane Doe" }} />',
    },
    {
      title: 'With action',
      code: '<User name="Jane Doe" description="Admin"><IconButton aria-label="More" /></User>',
    },
  ],
  dependencies: ['@cascivo/core'],
  registryDependencies: ['avatar'],
  tags: ['user', 'avatar', 'identity', 'display'],
  intent: {
    whenToUse: [
      'Showing a person with their name and a secondary line (email, role) next to an avatar',
      'Identity rows inside menus, tables, navbars, and account switchers',
      'A compact, labelled identity primitive too granular for a page-section block',
    ],
    whenNotToUse: [
      'Just an image with no name/description — use Avatar directly',
      'A full profile card with rich content — compose a Card instead',
    ],
    antiPatterns: [
      {
        bad: '<User name="" avatarProps={{ src: "/jane.jpg" }} />',
        good: '<User name="Jane Doe" avatarProps={{ src: "/jane.jpg", alt: "Jane Doe" }} />',
        why: 'The name is the accessible identity label; an empty name leaves the avatar unlabelled',
      },
    ],
    related: [
      {
        name: 'Avatar',
        relationship: 'contains',
        reason: 'User wraps Avatar and forwards avatarProps to it',
      },
      {
        name: 'AvatarGroup',
        relationship: 'alternative',
        reason: 'Use AvatarGroup to show several identities as an overlapping stack',
      },
    ],
    a11yRationale:
      'The composite is a labelled group; the name provides the accessible identity and the avatar carries its own role="img"/alt — no redundant roles',
    flexibility: [
      {
        area: 'description',
        level: 'flexible',
        note: 'Any ReactNode — email, role, or a status line',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Name and description colors must resolve to --cascivo-* tokens',
      },
    ],
  },
}
